(() => {
  "use strict";
  const root = document.querySelector("[data-panel-app]");
  const tokenKey = "prisma-panel-session";
  const esc = (value = "") => String(value).replace(/[&<>"']/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));
  const api = async (path, options = {}) => {
    const token = sessionStorage.getItem(tokenKey);
    const headers = new Headers(options.headers || {});
    if (token) headers.set("Authorization", `Bearer ${token}`);
    if (options.body && !(options.body instanceof FormData) && !headers.has("Content-Type")) headers.set("Content-Type", "application/json");
    const response = await fetch(path, {...options, headers});
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Não foi possível concluir a operação.");
    return data;
  };
  const shell = (content) => `<div class="panel-shell"><aside class="panel-sidebar"><a class="brand panel-brand" href="/"><span class="brand-word">PRISMA</span><span class="panel-brand-label">Editorial</span></a><p class="panel-sidebar__eyebrow">Gestão de conteúdo</p><nav class="panel-nav"><a href="/painel/" aria-current="page"><span><strong>Cases</strong><small>Portfólio das frentes</small></span></a><a href="/" target="_blank"><span><strong>Ver site</strong><small>Abrir uma nova aba</small></span></a></nav><div class="panel-sidebar__bottom"><div class="panel-theme"><p>Versão visual</p><div class="theme-switcher"><button class="theme-choice" data-theme-choice="golden">Golden</button><button class="theme-choice" data-theme-choice="solar">Solar</button></div></div><div class="panel-user"><span class="panel-user__avatar">P</span><span class="panel-user__identity"><strong>Equipe Prisma</strong><small>Acesso editorial</small></span><button class="panel-logout" type="button" data-logout title="Sair">↪</button></div></div></aside><div class="panel-main">${content}</div></div>`;
  const input = (id, name, label, value, opts = "") => `<div class="panel-field ${opts}"><label for="${id}">${label} <span>*</span></label><input class="panel-control" id="${id}" name="${name}" value="${esc(value)}"></div>`;
  const caseForm = (item = {}) => `<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><a class="panel-back-link" href="/painel/">← Voltar para cases</a><p class="panel-kicker">${item.slug ? "Editar case" : "Novo case"}</p><h1>${item.slug ? "Ajustar o case." : "Criar um case."}</h1><p>Associe o trabalho à frente principal e publique apenas informações autorizadas.</p></div></header><form data-case-form><div class="panel-editor"><div><section class="panel-form-section"><header class="panel-form-section__header"><span>01</span><div><h2>Posicionamento</h2><p>O que vai aparecer na listagem de cases.</p></div></header><div class="panel-form-grid"><div class="panel-field"><label for="id_front">Frente <span>*</span></label><select class="panel-control panel-select" id="id_front" name="front" required><option value="">Selecione</option><option value="marketing" ${item.front === "marketing" ? "selected" : ""}>Marketing</option><option value="tecnologia" ${item.front === "tecnologia" ? "selected" : ""}>Tecnologia</option></select></div><div class="panel-field"><label for="id_status">Status <span>*</span></label><select class="panel-control panel-select" id="id_status" name="status"><option value="draft" ${item.status !== "published" ? "selected" : ""}>Rascunho</option><option value="published" ${item.status === "published" ? "selected" : ""}>Publicado</option></select></div><div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_title">Título <span>*</span></label><span data-count-for="id_title">0 / 120</span></div><input class="panel-control" id="id_title" name="title" maxlength="120" required value="${esc(item.title)}"></div>${input("id_category", "category", "Categoria", item.category)}${input("id_deliverables", "deliverables", "Entregáveis", item.deliverables)}<div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_summary">Resumo <span>*</span></label><span data-count-for="id_summary">0 / 240</span></div><textarea class="panel-control" id="id_summary" name="summary" maxlength="240" required>${esc(item.summary)}</textarea></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>02</span><div><h2>Imagens do case</h2><p>Envie até cinco imagens JPG, PNG, WebP ou AVIF. Máximo de 8 MB por arquivo.</p></div></header><div class="panel-field panel-field--full"><label for="id_images">Galeria</label><input class="panel-control panel-file" id="id_images" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple><p class="panel-field__help">As imagens aparecerão em uma galeria com rolagem na página do case.</p><div class="panel-media-grid" data-media-grid></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>03</span><div><h2>História do projeto</h2><p>Contexto que aparece na página individual do case.</p></div></header><div class="panel-form-grid panel-form-grid--narrative"><div class="panel-field"><label for="id_challenge">O desafio <span>*</span></label><textarea class="panel-control" id="id_challenge" name="challenge" required>${esc(item.challenge)}</textarea></div><div class="panel-field"><label for="id_solution">A solução <span>*</span></label><textarea class="panel-control" id="id_solution" name="solution" required>${esc(item.solution)}</textarea></div><div class="panel-field panel-field--full"><label for="id_external_url">Link do botão Acessar <span class="optional">opcional</span></label><input class="panel-control" id="id_external_url" name="external_url" type="url" value="${esc(item.external_url)}" placeholder="https://"></div><label class="panel-checkbox-field panel-field--full"><input class="panel-checkbox" name="featured" type="checkbox" ${item.featured ? "checked" : ""}><span><strong>Destacar no portfólio</strong><span>O case recebe maior evidência na grade.</span></span></label></div></section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><a class="panel-cancel" href="/painel/">Cancelar</a><button class="button" type="submit">${item.slug ? "Salvar alterações" : "Criar case"} <span>↗</span></button></div></div><aside class="panel-editor__summary"><div class="panel-editor-summary-card"><span class="panel-summary-front" data-summary-front>Frente do case</span><h2 data-summary-title>Case sem título</h2><dl><div><dt>Status</dt><dd data-summary-status>Rascunho</dd></div><div><dt>Imagens</dt><dd data-summary-images>0 / 5</dd></div></dl><p class="panel-editor-summary-card__note">A galeria fica disponível para todos os cases publicados.</p></div></aside></div></form></main>`;
  function controls() {
    document.querySelector("[data-logout]")?.addEventListener("click", () => { sessionStorage.removeItem(tokenKey); login(); });
    document.querySelectorAll("[data-theme-choice]").forEach((button) => button.addEventListener("click", () => { document.documentElement.dataset.theme = button.dataset.themeChoice; localStorage.setItem("prisma-theme", button.dataset.themeChoice); }));
    const nav = document.querySelector(".panel-nav");
    if (nav && !nav.querySelector("[data-show-contact]")) {
      const button = document.createElement("button");
      button.type = "button"; button.className = "panel-nav-action"; button.dataset.showContact = "";
      button.innerHTML = "<span><strong>Dados de contato</strong><small>Canais públicos da Prisma</small></span>";
      nav.append(button); button.addEventListener("click", contacts);
    }
    if (nav && !nav.querySelector("[data-show-team]")) {
      const button = document.createElement("button");
      button.type = "button"; button.className = "panel-nav-action"; button.dataset.showTeam = "";
      button.innerHTML = "<span><strong>Sobre nós</strong><small>Perfis da equipe</small></span>";
      nav.append(button); button.addEventListener("click", teamEditor);
    }
    if (nav && !nav.querySelector("[data-show-content]")) {
      const button = document.createElement("button");
      button.type = "button"; button.className = "panel-nav-action"; button.dataset.showContent = "";
      button.innerHTML = "<span><strong>Conteúdos</strong><small>Provas, marcas e insights</small></span>";
      nav.append(button); button.addEventListener("click", contentEditor);
    }
    if (nav && !nav.querySelector("[data-show-services]")) {
      const button = document.createElement("button");
      button.type = "button"; button.className = "panel-nav-action"; button.dataset.showServices = "";
      button.innerHTML = "<span><strong>Serviços</strong><small>Catálogo e recorrência</small></span>";
      nav.append(button); button.addEventListener("click", serviceEditor);
    }
  }
  const frameStyle = (image) => `object-fit:${image.fit === "cover" ? "cover" : "contain"};object-position:${Number(image.position_x ?? 50)}% ${Number(image.position_y ?? 50)}%;transform-origin:${Number(image.position_x ?? 50)}% ${Number(image.position_y ?? 50)}%;transform:scale(${Number(image.zoom ?? 100) / 100})`;
  function drawMedia(grid, images, refresh) {
    grid.innerHTML = images.length ? images.map((image, index) => `<figure class="panel-media-card" data-image-card="${index}"><div class="panel-media-card__preview"><img src="${esc(image.preview || image.url)}" alt="" style="${frameStyle(image)}"></div><figcaption><span>Imagem ${index + 1}</span><button type="button" data-remove-image="${index}">Remover</button></figcaption><div class="panel-image-controls"><label>Exibição<select data-image-fit="${index}"><option value="contain" ${image.fit !== "cover" ? "selected" : ""}>Mostrar inteira</option><option value="cover" ${image.fit === "cover" ? "selected" : ""}>Preencher espaço</option></select></label><label>Zoom <output data-image-zoom-output="${index}">${image.zoom || 100}%</output><input type="range" min="100" max="200" value="${image.zoom || 100}" data-image-zoom="${index}"></label><div class="panel-image-controls__position"><label>Horizontal<input type="range" min="0" max="100" value="${image.position_x ?? 50}" data-image-x="${index}"></label><label>Vertical<input type="range" min="0" max="100" value="${image.position_y ?? 50}" data-image-y="${index}"></label></div><p>Use “Mostrar inteira” para evitar cortes. Em “Preencher espaço”, ajuste o foco e o zoom.</p></div></figure>`).join("") : '<p class="panel-media-empty">Nenhuma imagem adicionada. A galeria é opcional.</p>';
    const updateCard = (index) => { const image = images[index], card = grid.querySelector(`[data-image-card="${index}"]`); if (!card) return; card.querySelector("img").style.cssText = frameStyle(image); card.querySelector(`[data-image-zoom-output="${index}"]`).textContent = `${image.zoom}%`; };
    grid.querySelectorAll("[data-remove-image]").forEach((button) => button.addEventListener("click", () => { images.splice(Number(button.dataset.removeImage), 1); refresh(); }));
    grid.querySelectorAll("[data-image-fit]").forEach((field) => field.addEventListener("change", () => { const index = Number(field.dataset.imageFit); images[index].fit = field.value; updateCard(index); }));
    grid.querySelectorAll("[data-image-zoom]").forEach((field) => field.addEventListener("input", () => { const index = Number(field.dataset.imageZoom); images[index].zoom = Number(field.value); updateCard(index); }));
    grid.querySelectorAll("[data-image-x]").forEach((field) => field.addEventListener("input", () => { const index = Number(field.dataset.imageX); images[index].position_x = Number(field.value); updateCard(index); }));
    grid.querySelectorAll("[data-image-y]").forEach((field) => field.addEventListener("input", () => { const index = Number(field.dataset.imageY); images[index].position_y = Number(field.value); updateCard(index); }));
  }
  async function dashboard() {
    try {
      const {cases} = await api("/api/cases");
      const cards = cases.length ? cases.map((item) => `<article class="panel-project"><div class="panel-project__visual">${item.images?.[0] ? `<img src="${esc(item.images[0].url)}" alt="">` : '<div class="panel-project__art"><span></span></div>'}</div><div class="panel-project__body"><div class="panel-project__badges"><span class="panel-badge">${item.front === "marketing" ? "Marketing" : "Tecnologia"}</span><span class="panel-badge panel-badge--${item.status}">${item.status === "published" ? "Publicado" : "Rascunho"}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><div class="panel-project__meta"><span>${esc(item.category)}</span><span>${item.images?.length || 0} imagem(ns)</span></div></div><div class="panel-project__actions"><button class="panel-action panel-action--primary" data-edit="${esc(item.slug)}">Editar →</button><a class="panel-action" href="/case.html?slug=${encodeURIComponent(item.slug)}" target="_blank">Ver página ↗</a></div></article>`).join("") : '<div class="panel-empty-state"><p class="panel-kicker">Portfólio vazio</p><h3>O próximo case começa aqui.</h3></div>';
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header"><div><p class="panel-kicker">Painel editorial</p><h1>Cases em movimento.</h1><p>Administre os trabalhos de Marketing e Tecnologia.</p></div><button class="button" data-new-case>Novo case <span>↗</span></button></header><section class="panel-collection"><header class="panel-collection__heading"><div><p class="panel-kicker">Biblioteca</p><h2>Cases cadastrados</h2></div><p>${cases.length} item(ns).</p></header><div class="panel-project-list">${cards}</div></section></main>`);
      controls(); document.querySelector("[data-new-case]")?.addEventListener("click", () => form());
      document.querySelectorAll("[data-edit]").forEach((button) => button.addEventListener("click", () => form(cases.find((item) => item.slug === button.dataset.edit))));
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  async function contacts() {
    try {
      const {contact = {}} = await api("/api/settings");
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><button class="panel-back-link" type="button" data-back-to-cases>← Voltar para cases</button><p class="panel-kicker">Dados institucionais</p><h1>Canais de contato.</h1><p>Essas informações aparecem na seção de contato da página inicial.</p></div></header><form data-contact-settings><div class="panel-editor"><div><section class="panel-form-section"><header class="panel-form-section__header"><span>01</span><div><h2>Contato direto</h2><p>Inclua apenas os canais que podem ser publicados.</p></div></header><div class="panel-form-grid"><div class="panel-field"><label for="contact_email">E-mail</label><input class="panel-control" id="contact_email" name="email" type="email" value="${esc(contact.email)}" placeholder="contato@empresa.com.br"></div><div class="panel-field"><label for="contact_phone">Telefone</label><input class="panel-control" id="contact_phone" name="phone" value="${esc(contact.phone)}" placeholder="(00) 0000-0000"></div><div class="panel-field panel-field--full"><label for="contact_whatsapp">WhatsApp</label><input class="panel-control" id="contact_whatsapp" name="whatsapp" value="${esc(contact.whatsapp)}" placeholder="(00) 00000-0000"></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>02</span><div><h2>Atendimento e canais</h2><p>Detalhes que ajudam uma nova conversa a começar.</p></div></header><div class="panel-form-grid"><div class="panel-field"><label for="contact_availability">Disponibilidade</label><input class="panel-control" id="contact_availability" name="availability" value="${esc(contact.availability)}" placeholder="Segunda a sexta, das 9h às 18h"></div><div class="panel-field"><label for="contact_location">Localização</label><input class="panel-control" id="contact_location" name="location" value="${esc(contact.location)}" placeholder="Brasil · atendimento remoto"></div><div class="panel-field"><label for="contact_instagram">Instagram</label><input class="panel-control" id="contact_instagram" name="instagram_url" type="url" value="${esc(contact.instagram_url)}" placeholder="https://instagram.com/... "></div><div class="panel-field"><label for="contact_linkedin">LinkedIn</label><input class="panel-control" id="contact_linkedin" name="linkedin_url" type="url" value="${esc(contact.linkedin_url)}" placeholder="https://linkedin.com/company/... "></div></div></section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><button class="panel-cancel" type="button" data-back-to-cases>Cancelar</button><button class="button" type="submit">Salvar dados <span>↗</span></button></div></div><aside class="panel-editor__summary"><div class="panel-editor-summary-card"><span class="panel-summary-front">Publicação</span><h2>Contato da Prisma</h2><p class="panel-editor-summary-card__note">Os campos preenchidos substituem os textos provisórios da página inicial.</p></div></aside></div></form></main>`);
      controls();
      root.querySelectorAll("[data-back-to-cases]").forEach((button) => button.addEventListener("click", dashboard));
      root.querySelector("[data-contact-settings]").addEventListener("submit", async (event) => {
        event.preventDefault(); const form = event.currentTarget, error = form.querySelector("[data-form-error]"); error.hidden = true;
        try { await api("/api/settings", {method: "PUT", body: JSON.stringify(Object.fromEntries(new FormData(form)))}); dashboard(); }
        catch (reason) { error.textContent = reason.message; error.hidden = false; }
      });
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  const contentSlots = (items, count, defaults) => Array.from({length: count}, (_, index) => ({...defaults, ...(items?.[index] || {})}));
  const testimonialCard = (item, index) => `<article class="panel-content-card"><p class="panel-content-card__number">Depoimento ${index + 1}</p><div class="panel-field"><label for="testimonial_quote_${index}">Depoimento</label><textarea class="panel-control" id="testimonial_quote_${index}" data-testimonial-quote="${index}" maxlength="700" placeholder="Use apenas uma fala autorizada.">${esc(item.quote)}</textarea></div><div class="panel-field"><label for="testimonial_author_${index}">Pessoa</label><input class="panel-control" id="testimonial_author_${index}" data-testimonial-author="${index}" maxlength="100" value="${esc(item.author)}" placeholder="Nome"></div><div class="panel-field"><label for="testimonial_role_${index}">Cargo ou empresa</label><input class="panel-control" id="testimonial_role_${index}" data-testimonial-role="${index}" maxlength="140" value="${esc(item.role)}" placeholder="Cargo · Empresa"></div><label class="panel-checkbox-field"><input class="panel-checkbox" type="checkbox" data-testimonial-visible="${index}" ${item.visible ? "checked" : ""}><span><strong>Publicar depoimento</strong><span>Confirme a autorização antes de publicar.</span></span></label></article>`;
  const partnerCard = (item, index) => `<article class="panel-content-card"><p class="panel-content-card__number">Marca ${index + 1}</p><div class="panel-partner-logo" data-partner-preview="${index}">${item.preview || item.logo?.url ? `<img src="${esc(item.preview || item.logo.url)}" alt="">` : `<span>${esc(initials(item.name))}</span>`}</div><div class="panel-field"><label for="partner_logo_${index}">Logo <span class="optional">opcional</span></label><input class="panel-control panel-file" id="partner_logo_${index}" type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-partner-logo="${index}"></div><div class="panel-field"><label for="partner_name_${index}">Nome da marca</label><input class="panel-control" id="partner_name_${index}" data-partner-name="${index}" maxlength="100" value="${esc(item.name)}" placeholder="Marca ou cliente"></div><div class="panel-field"><label for="partner_url_${index}">Site <span class="optional">opcional</span></label><input class="panel-control" id="partner_url_${index}" type="url" data-partner-url="${index}" value="${esc(item.url)}" placeholder="https://"></div><label class="panel-checkbox-field"><input class="panel-checkbox" type="checkbox" data-partner-authorised="${index}" ${item.authorised ? "checked" : ""}><span><strong>Autorizado para publicação</strong><span>A marca só aparece no site com esta confirmação.</span></span></label></article>`;
  const insightCard = (item, index) => `<article class="panel-content-card"><p class="panel-content-card__number">Insight ${index + 1}</p><div class="panel-field"><label for="insight_title_${index}">Título</label><input class="panel-control" id="insight_title_${index}" data-insight-title="${index}" maxlength="140" value="${esc(item.title)}" placeholder="Assunto do conteúdo"></div><div class="panel-field"><label for="insight_category_${index}">Categoria</label><input class="panel-control" id="insight_category_${index}" data-insight-category="${index}" maxlength="70" value="${esc(item.category)}" placeholder="Ex.: Estratégia"></div><div class="panel-field"><label for="insight_summary_${index}">Resumo</label><textarea class="panel-control" id="insight_summary_${index}" data-insight-summary="${index}" maxlength="400" placeholder="Uma breve introdução.">${esc(item.summary)}</textarea></div><div class="panel-field"><label for="insight_url_${index}">Link <span class="optional">opcional</span></label><input class="panel-control" id="insight_url_${index}" type="url" data-insight-url="${index}" value="${esc(item.url)}" placeholder="https://"></div><div class="panel-field"><label for="insight_date_${index}">Data</label><input class="panel-control" id="insight_date_${index}" type="date" data-insight-date="${index}" value="${esc(item.published_at)}"></div><label class="panel-checkbox-field"><input class="panel-checkbox" type="checkbox" data-insight-visible="${index}" ${item.visible ? "checked" : ""}><span><strong>Publicar insight</strong><span>O conteúdo aparecerá na página inicial.</span></span></label></article>`;
  async function contentEditor() {
    try {
      const {content = {}} = await api("/api/content");
      const testimonials = contentSlots(content.testimonials, 3, {quote: "", author: "", role: "", visible: false});
      const partners = contentSlots(content.partners, 6, {name: "", url: "", logo: null, authorised: false});
      const insights = contentSlots(content.insights, 4, {title: "", category: "", summary: "", url: "", published_at: "", visible: false});
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><button class="panel-back-link" type="button" data-back-to-cases>← Voltar para cases</button><p class="panel-kicker">Repertório e confiança</p><h1>Conteúdos que comprovam.</h1><p>Registre somente informações e referências que podem ser divulgadas.</p></div></header><form data-content-settings><section class="panel-content-section"><header class="panel-form-section__header"><span>01</span><div><h2>Depoimentos</h2><p>Até três falas autorizadas de clientes ou parceiros.</p></div></header><div class="panel-content-grid">${testimonials.map(testimonialCard).join("")}</div></section><section class="panel-content-section"><header class="panel-form-section__header"><span>02</span><div><h2>Marcas e parceiros</h2><p>Até seis marcas, visíveis somente após a confirmação de autorização.</p></div></header><div class="panel-content-grid panel-content-grid--brands">${partners.map(partnerCard).join("")}</div></section><section class="panel-content-section"><header class="panel-form-section__header"><span>03</span><div><h2>Insights</h2><p>Até quatro conteúdos para revelar repertório, método e ponto de vista.</p></div></header><div class="panel-content-grid">${insights.map(insightCard).join("")}</div></section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><button class="panel-cancel" type="button" data-back-to-cases>Cancelar</button><button class="button" type="submit">Salvar conteúdos <span>↗</span></button></div></form></main>`);
      controls(); root.querySelectorAll("[data-back-to-cases]").forEach((button) => button.addEventListener("click", dashboard));
      const refreshPartners = () => partners.forEach((partner, index) => { const preview = root.querySelector(`[data-partner-preview="${index}"]`); if (preview) preview.innerHTML = partner.preview || partner.logo?.url ? `<img src="${esc(partner.preview || partner.logo.url)}" alt="">` : `<span>${esc(initials(partner.name))}</span>`; });
      root.querySelectorAll("[data-partner-logo]").forEach((field) => field.addEventListener("change", () => { const index = Number(field.dataset.partnerLogo), file = field.files?.[0]; if (!file) return; if (!/image\/(avif|jpeg|png|webp)/.test(file.type) || file.size > 8 * 1024 * 1024) { alert("Envie uma imagem JPG, PNG, WebP ou AVIF de até 8 MB."); field.value = ""; return; } partners[index].file = file; partners[index].preview = URL.createObjectURL(file); refreshPartners(); }));
      root.querySelectorAll("[data-partner-name]").forEach((field) => field.addEventListener("input", () => { partners[Number(field.dataset.partnerName)].name = field.value; refreshPartners(); }));
      root.querySelector("[data-content-settings]").addEventListener("submit", async (event) => {
        event.preventDefault(); const form = event.currentTarget, error = form.querySelector("[data-form-error]"), submit = form.querySelector("button[type=submit]"); error.hidden = true; submit.disabled = true;
        try {
          const value = (name, index) => root.querySelector(`[data-${name}="${index}"]`).value.trim(), checked = (name, index) => root.querySelector(`[data-${name}="${index}"]`).checked;
          testimonials.forEach((item, index) => Object.assign(item, {quote: value("testimonial-quote", index), author: value("testimonial-author", index), role: value("testimonial-role", index), visible: checked("testimonial-visible", index)}));
          partners.forEach((item, index) => Object.assign(item, {name: value("partner-name", index), url: value("partner-url", index), authorised: checked("partner-authorised", index)}));
          insights.forEach((item, index) => Object.assign(item, {title: value("insight-title", index), category: value("insight-category", index), summary: value("insight-summary", index), url: value("insight-url", index), published_at: value("insight-date", index), visible: checked("insight-visible", index)}));
          for (const partner of partners.filter((item) => item.file)) { const upload = new FormData(); upload.append("scope", "partners"); upload.append("image", partner.file); const {image} = await api("/api/media", {method: "POST", body: upload}); partner.logo = image; delete partner.file; delete partner.preview; }
          await api("/api/content", {method: "PUT", body: JSON.stringify({testimonials, partners, insights})}); dashboard();
        } catch (reason) { error.textContent = reason.message; error.hidden = false; submit.disabled = false; }
      });
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  const serviceCard = (service, index) => `<article class="panel-service-card"><header><span>Serviço ${String(index + 1).padStart(2, "0")}</span><button type="button" data-remove-service="${index}">Remover</button></header><div class="panel-form-grid"><div class="panel-field"><label for="service_front_${index}">Frente</label><select class="panel-control panel-select" id="service_front_${index}" data-service-front="${index}"><option value="tecnologia" ${service.front === "tecnologia" ? "selected" : ""}>Tecnologia</option><option value="marketing" ${service.front === "marketing" ? "selected" : ""}>Marketing</option><option value="integrado" ${service.front === "integrado" ? "selected" : ""}>Integrado</option></select></div><div class="panel-field"><label for="service_title_${index}">Nome do serviço</label><input class="panel-control" id="service_title_${index}" data-service-title="${index}" maxlength="120" value="${esc(service.title)}" placeholder="Ex.: Desenvolvimento de sites"></div><div class="panel-field panel-field--full"><label for="service_summary_${index}">Descrição</label><textarea class="panel-control" id="service_summary_${index}" data-service-summary="${index}" maxlength="500" placeholder="O que este serviço entrega e para quem.">${esc(service.summary)}</textarea></div><div class="panel-field"><label for="service_price_${index}">Valor inicial <span class="optional">opcional</span></label><input class="panel-control" id="service_price_${index}" data-service-price="${index}" maxlength="80" value="${esc(service.starting_price)}" placeholder="Ex.: A partir de R$ 3.500"></div><div class="panel-field"><label for="service_support_price_${index}">Valor recorrente <span class="optional">opcional</span></label><input class="panel-control" id="service_support_price_${index}" data-service-support-price="${index}" maxlength="80" value="${esc(service.support_price)}" placeholder="Ex.: A partir de R$ 490/mês"></div><div class="panel-field panel-field--full"><label for="service_support_${index}">Suporte à rotina <span class="optional">opcional</span></label><textarea class="panel-control" id="service_support_${index}" data-service-support="${index}" maxlength="280" placeholder="Ex.: manutenção mensal, evolução contínua e acompanhamento de indicadores.">${esc(service.support_summary)}</textarea></div><label class="panel-checkbox-field panel-field--full"><input class="panel-checkbox" type="checkbox" data-service-visible="${index}" ${service.visible ? "checked" : ""}><span><strong>Exibir no site</strong><span>O serviço aparecerá na seção pública correspondente.</span></span></label></div></article>`;
  async function serviceEditor() {
    try {
      const response = await api("/api/services");
      let services = (response.services || []).map((service) => ({front: "tecnologia", title: "", summary: "", starting_price: "", support_summary: "", support_price: "", visible: false, ...service}));
      const render = () => {
        root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><button class="panel-back-link" type="button" data-back-to-cases>← Voltar para cases</button><p class="panel-kicker">Catálogo comercial</p><h1>Serviços da Prisma.</h1><p>Cadastre entregas, valor inicial e como cada serviço pode receber suporte contínuo.</p></div><button class="button" type="button" data-add-service>Novo serviço <span>+</span></button></header><form data-service-settings><section class="panel-service-list">${services.length ? services.map(serviceCard).join("") : '<div class="panel-empty-state"><p class="panel-kicker">Catálogo vazio</p><h3>Cadastre a primeira entrega.</h3><p>Você pode incluir valor inicial e condições de suporte recorrente.</p></div>'}</section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><button class="panel-cancel" type="button" data-back-to-cases>Cancelar</button><button class="button" type="submit">Salvar serviços <span>↗</span></button></div></form></main>`);
        controls(); root.querySelectorAll("[data-back-to-cases]").forEach((button) => button.addEventListener("click", dashboard));
        root.querySelector("[data-add-service]").addEventListener("click", () => { if (services.length >= 24) return alert("O catálogo aceita até 24 serviços."); services.push({front: "tecnologia", title: "", summary: "", starting_price: "", support_summary: "", support_price: "", visible: false}); render(); });
        root.querySelectorAll("[data-remove-service]").forEach((button) => button.addEventListener("click", () => { services.splice(Number(button.dataset.removeService), 1); render(); }));
        root.querySelector("[data-service-settings]").addEventListener("submit", async (event) => {
          event.preventDefault(); const form = event.currentTarget, error = form.querySelector("[data-form-error]"), submit = form.querySelector("button[type=submit]"); error.hidden = true; submit.disabled = true;
          try {
            const value = (name, index) => root.querySelector(`[data-${name}="${index}"]`).value.trim(), checked = (name, index) => root.querySelector(`[data-${name}="${index}"]`).checked;
            services = services.map((service, index) => ({...service, front: value("service-front", index), title: value("service-title", index), summary: value("service-summary", index), starting_price: value("service-price", index), support_price: value("service-support-price", index), support_summary: value("service-support", index), visible: checked("service-visible", index)}));
            await api("/api/services", {method: "PUT", body: JSON.stringify(services)}); dashboard();
          } catch (reason) { error.textContent = reason.message; error.hidden = false; submit.disabled = false; }
        });
      };
      render();
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  const initials = (name = "") => name.trim().split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word[0]).join("").toUpperCase() || "P";
  const teamCard = (member, index) => `<article class="panel-team-card" data-team-card="${index}"><div class="panel-team-card__photo" data-team-preview="${index}">${member.preview || member.photo?.url ? `<img src="${esc(member.preview || member.photo.url)}" alt="">` : `<span>${esc(initials(member.name))}</span>`}</div><div class="panel-team-card__heading"><span>Perfil ${index + 1}</span><button type="button" data-remove-team-photo="${index}" ${member.photo || member.preview ? "" : "hidden"}>Remover foto</button></div><div class="panel-field"><label for="team_photo_${index}">Foto <span class="optional">opcional</span></label><input class="panel-control panel-file" id="team_photo_${index}" type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-team-photo="${index}"></div><div class="panel-field"><label for="team_name_${index}">Nome</label><input class="panel-control" id="team_name_${index}" maxlength="100" value="${esc(member.name)}" data-team-name="${index}" placeholder="Nome da pessoa"></div><div class="panel-field"><label for="team_role_${index}">Cargo</label><input class="panel-control" id="team_role_${index}" maxlength="100" value="${esc(member.role)}" data-team-role="${index}" placeholder="Ex.: Direção de arte"></div><div class="panel-field"><label for="team_bio_${index}">Breve bio</label><textarea class="panel-control" id="team_bio_${index}" maxlength="700" data-team-bio="${index}" placeholder="Apresente a pessoa em poucas linhas.">${esc(member.bio)}</textarea></div></article>`;
  async function teamEditor() {
    try {
      const response = await api("/api/team");
      const members = [0, 1, 2].map((index) => ({id: `member-${index + 1}`, name: "", role: "", bio: "", photo: null, ...(response.team?.[index] || {})}));
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><button class="panel-back-link" type="button" data-back-to-cases>← Voltar para cases</button><p class="panel-kicker">Identidade da Prisma</p><h1>Sobre nós.</h1><p>Apresente até três pessoas que dão forma ao trabalho da Prisma.</p></div></header><form data-team-settings><section class="panel-team-list">${members.map(teamCard).join("")}</section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><button class="panel-cancel" type="button" data-back-to-cases>Cancelar</button><button class="button" type="submit">Salvar equipe <span>↗</span></button></div></form></main>`);
      controls();
      root.querySelectorAll("[data-back-to-cases]").forEach((button) => button.addEventListener("click", dashboard));
      const refresh = () => {
        members.forEach((member, index) => {
          const preview = root.querySelector(`[data-team-preview="${index}"]`);
          const remove = root.querySelector(`[data-remove-team-photo="${index}"]`);
          if (preview) preview.innerHTML = member.preview || member.photo?.url ? `<img src="${esc(member.preview || member.photo.url)}" alt="">` : `<span>${esc(initials(member.name))}</span>`;
          if (remove) remove.hidden = !(member.preview || member.photo);
        });
      };
      root.querySelectorAll("[data-team-photo]").forEach((field) => field.addEventListener("change", () => {
        const index = Number(field.dataset.teamPhoto), file = field.files?.[0];
        if (!file) return;
        if (!/image\/(avif|jpeg|png|webp)/.test(file.type)) { alert("Envie uma imagem JPG, PNG, WebP ou AVIF."); field.value = ""; return; }
        if (file.size > 8 * 1024 * 1024) { alert("A foto pode ter no máximo 8 MB."); field.value = ""; return; }
        members[index].file = file; members[index].preview = URL.createObjectURL(file); refresh();
      }));
      root.querySelectorAll("[data-remove-team-photo]").forEach((button) => button.addEventListener("click", () => {
        const member = members[Number(button.dataset.removeTeamPhoto)]; delete member.file; delete member.preview; member.photo = null; refresh();
      }));
      root.querySelectorAll("[data-team-name]").forEach((field) => field.addEventListener("input", () => { members[Number(field.dataset.teamName)].name = field.value; refresh(); }));
      root.querySelector("[data-team-settings]").addEventListener("submit", async (event) => {
        event.preventDefault(); const form = event.currentTarget, error = form.querySelector("[data-form-error]"), submit = form.querySelector("button[type=submit]"); error.hidden = true; submit.disabled = true;
        try {
          members.forEach((member, index) => { member.name = root.querySelector(`[data-team-name="${index}"]`).value.trim(); member.role = root.querySelector(`[data-team-role="${index}"]`).value.trim(); member.bio = root.querySelector(`[data-team-bio="${index}"]`).value.trim(); });
          for (const member of members.filter((member) => member.file)) { const upload = new FormData(); upload.append("scope", "team"); upload.append("image", member.file); const {image} = await api("/api/media", {method: "POST", body: upload}); member.photo = image; delete member.file; delete member.preview; }
          await api("/api/team", {method: "PUT", body: JSON.stringify(members.map(({name, role, bio, photo}) => ({name, role, bio, photo})))}); dashboard();
        } catch (reason) { error.textContent = reason.message; error.hidden = false; submit.disabled = false; }
      });
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  function form(item = {}) {
    root.innerHTML = shell(caseForm(item)); controls();
    const editor = document.querySelector("[data-case-form]"), grid = editor.querySelector("[data-media-grid]"), images = (item.images || []).map((image) => ({...image}));
    const results = contentSlots(item.results, 3, {label: "", value: "", detail: ""});
    editor.querySelector("[data-form-error]").insertAdjacentHTML("beforebegin", `<section class="panel-form-section"><header class="panel-form-section__header"><span>04</span><div><h2>Impactos e resultados</h2><p>Inclua até três indicadores reais e verificáveis. Esta área é opcional.</p></div></header><div class="panel-results-editor">${results.map((result, index) => `<div class="panel-result-row"><span>${String(index + 1).padStart(2, "0")}</span><input class="panel-control" data-result-label="${index}" maxlength="80" value="${esc(result.label)}" placeholder="Indicador"><input class="panel-control" data-result-value="${index}" maxlength="80" value="${esc(result.value)}" placeholder="Resultado"><input class="panel-control" data-result-detail="${index}" maxlength="180" value="${esc(result.detail)}" placeholder="Contexto opcional"></div>`).join("")}</div></section>`);
    const updateMedia = () => { drawMedia(grid, images, updateMedia); editor.querySelector("[data-summary-images]").textContent = `${images.length} / 5`; };
    updateMedia();
    editor.querySelector("#id_images").addEventListener("change", (event) => {
      const files = [...event.target.files];
      if (images.length + files.length > 5) { alert("Cada case pode ter no máximo cinco imagens."); event.target.value = ""; return; }
      files.forEach((file) => images.push({file, preview: URL.createObjectURL(file), fit: "contain", position_x: 50, position_y: 50, zoom: 100})); event.target.value = ""; updateMedia();
    });
    const sync = () => { editor.querySelector("[data-summary-title]").textContent = editor.title.value.trim() || "Case sem título"; editor.querySelector("[data-summary-front]").textContent = editor.front.selectedOptions[0]?.text || "Frente do case"; editor.querySelector("[data-summary-status]").textContent = editor.status.selectedOptions[0]?.text || "Rascunho"; };
    editor.addEventListener("input", sync); editor.addEventListener("change", sync); sync();
    editor.querySelectorAll("[data-count-for]").forEach((counter) => { const field = document.getElementById(counter.dataset.countFor); const count = () => counter.textContent = `${field.value.length} / ${field.maxLength}`; field.addEventListener("input", count); count(); });
    editor.addEventListener("submit", async (event) => {
      event.preventDefault(); const message = editor.querySelector("[data-form-error]"), submit = editor.querySelector("button[type=submit]"); message.hidden = true; submit.disabled = true;
      try {
        for (const image of images.filter((entry) => entry.file)) { const upload = new FormData(); upload.append("image", image.file); const {image: saved} = await api("/api/media", {method: "POST", body: upload}); Object.assign(image, saved); delete image.file; delete image.preview; }
        const data = Object.fromEntries(new FormData(editor)); data.featured = editor.featured.checked; data.images = images.map(({key, url, alt, fit, position_x, position_y, zoom}) => ({key, url, alt, fit, position_x, position_y, zoom})); data.results = results.map((result, index) => ({label: editor.querySelector(`[data-result-label="${index}"]`).value, value: editor.querySelector(`[data-result-value="${index}"]`).value, detail: editor.querySelector(`[data-result-detail="${index}"]`).value}));
        if (item.slug) data.slug = item.slug;
        await api("/api/cases", {method: item.slug ? "PUT" : "POST", body: JSON.stringify(data)}); dashboard();
      } catch (error) { message.textContent = error.message; message.hidden = false; submit.disabled = false; }
    });
  }
  function login(message = "") {
    root.innerHTML = `<main class="panel-login"><section class="panel-login__brand"><div class="panel-login__brand-inner"><a class="brand" href="/"><span class="brand-word">PRISMA</span></a><div class="panel-login__statement"><p class="panel-kicker">Área editorial</p><h1>Ideias em <em>movimento.</em></h1><p>Um espaço de trabalho para registrar e publicar os cases da Prisma.</p></div></div></section><section class="panel-login__access"><div class="panel-login__form-shell"><p class="panel-kicker">Acesso da equipe</p><h2>Entrar no painel.</h2><form class="panel-login-form" data-login-form><div class="panel-field"><label for="password">Senha</label><input class="panel-control" id="password" name="password" type="password" required autocomplete="current-password"></div>${message ? `<p class="panel-form-alert">${esc(message)}</p>` : ""}<button class="button panel-login__submit" type="submit">Entrar <span>→</span></button></form></div></section></main>`;
    root.querySelector("[data-login-form]").addEventListener("submit", async (event) => { event.preventDefault(); try { const {token} = await api("/api/session", {method: "POST", body: JSON.stringify({password: event.target.password.value})}); sessionStorage.setItem(tokenKey, token); dashboard(); } catch (error) { login(error.message); } });
  }
  sessionStorage.getItem(tokenKey) ? dashboard() : login();
})();
